// Declare global variables
let cam;// Camera object
let delta = 0.01;// A constant delta value

// Define the preload function to load images
function preload() {
	earth = loadImage("https://openprocessing.org/sketch/2168753/files/earth.jpg");// Load an image for Earth
  moon = loadImage("https://openprocessing.org/sketch/2168753/files/moon.jpg");// Load an image for the Moon
	milkyway = loadImage('https://openprocessing.org/sketch/2168753/files/night-and-stars.jpg');// Load a Milky Way image
	weather = loadImage('https://openprocessing.org/sketch/2168753/files/global-weather-large.png');// Load an image for weather
}

// Set up the initial sketch
function setup(){
	blendMode(DODGE)// Set blending mode
	//colorMode(HSB);
	smooth();// Enable anti-aliasing
	//simple();

	cnv = createCanvas(windowWidth,windowHeight, WEBGL); // Create a 3D canvas
  rat=1024/768;// Define an aspect ratio

	background(0, 0, 0);// Set the background color to black
	noStroke();// Disable drawing of strokes
	cam = createCamera();// Create a 3D camera
	camera(0, 0, 3000);// Set the initial camera position + sin(frameCount * 0.1) * 10, 40, 0, -700, 0, 1, 0);
  // set initial pan angle and tilt angle for the camera
  cam.pan(frameCount / 0.0002 );
	cam.tilt( frameCount / 0.0001 +0.1);
	cam.move(frameCount / 0.0002, delta, 0);

}

// Main rendering loop
function draw(){
	//Clean Frames by clearing the background
	background(0, 0, 0);

// Handle mouse interaction to control the camera's position
//		cnv.mousePressed(mousePressed);
		function mousePressed() {
		let camX = 350+ 480*sin(frameCount* 0.0001)/10;;
		let camY = 400+ 480*sin(frameCount* 0.0001)/10;;
		let camZ = 2000;
		camera(camX, camY, camZ + sin(frameCount * 0.8) * 10,  480*sin(frameCount* 0.01), 0, -700, 0, 1, 0);
	//camera([x], [y], [z], [centerX], [centerY], [centerZ], [upX], [upY], [upZ])
}

//	let alpha = sin(frameCount * 0.0000000000000001);

	//Set up global lighting
	directionalLight(40,40,40,-1,0,1);
	directionalLight(150,150,150,1,0,1);

	// Enable orbit control for camera manipulation
	orbitControl(1,0.6,0.1);
	// Rotate the scene based on frame count
	rotateX(-(frameCount * 0.0003));	
	rotateY(-(frameCount * 0.0002));
	rotateZ(-(frameCount * 0.0003));
	// Calculate the position of a point light based on the mouse position
	  let lX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width/4;
  	let lY =  (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height/4;

	// Create a point light source
	pointLight(250, 250, 250, -lX, -lY, 1);
	// Calculate positions for rendering objects
		let x = 480*sin(frameCount* 0.01);
		let y = 480*cos(frameCount* 0.02);
		let s = 480*sin(frameCount* 0.01);		
	console.log(x,y,s);

	// Render the universe background with a Milky Way texture
	push();																								//Universe
		directionalLight(220,225,255,1,1,0);
		rotateX(frameCount * 0.0002+10.0);	
		rotateY(+1.5);
		rotateZ(+ frameCount * 0.0001 +1.2);
		texture(milkyway);
		sphere(3200);
	pop();

	// Render the Sun and apply lighting effects
	push();																								//sun
		translate(1000,-400,800);	
		fill(255,204,0, 50);
//		sphere(200);	
		directionalLight(255,255,255,1,0,-1);	
		directionalLight(20,20,100,1,0,0);
		directionalLight(130,160,190,1,0,1);
	pop();

	// Translate and rotate for Earth's position
	translate(150,150,-600);	
  rotateY(frameCount * 0.003);
	rotateZ(frameCount * 0.002);

	// Render the Earth with its texture
	push();																								//Earth
		translate(350,380,-40);	
		directionalLight(255,255,255,1,0,-1);	
		directionalLight(20,20,100,1,0,0);
		directionalLight(130,160,190,1,0,1);
		rotateY(millis()/12000);
		texture(earth);
		sphere(150);
	pop(mousePressed);	
	// Render Earth's atmosphere
	push();																								//Athmosphere
		translate(350,380,-40);	
		rotateY(millis()/30000);	
		directionalLight(250,250,250,1,0,-1);
		directionalLight(130,160,190,1,0,1);
		texture(weather);
		sphere(152, 40);
	pop();
	// Render the Moon with a distance effect
	push();																								//Moon behind distence effect
		translate(350,380,-40);	
		directionalLight(180,180,180,1,0,-1);	
		directionalLight(40,50,60,-1,0,1);
		translate(x, y, s);
		texture(moon);
		sphere(15);
  pop();	
	 // Render the Moon with a distance effect as a box
push();																								//Moon behind distence effect
		translate(350,380,-40);	
		directionalLight(180,180,180,1,0,-1);	
		directionalLight(40,50,60,-1,0,1);
		translate(x, y, s);
		texture(moon);
		box(15);

